#define BG RGB15(1,0,4)
#define PANEL RGB15(7,3,14)
#define PANEL2 RGB15(12,5,24)
#define PURPLE RGB15(24,2,31)
static uint16_t accent_color=RGB15(31,4,31);
#define VIOLET accent_color
#define WHITE RGB15(31,29,31)
#define MUTED RGB15(17,13,21)
static void fit_text(char*out,size_t cap,const char*in,int maxpx){snprintf(out,cap,"%s",in?in:"");if(gfx_text_width(out,1)<=maxpx)return;size_t n=strlen(out);while(n>3&&gfx_text_width(out,1)>maxpx-24){n--;while(n>0&&(((unsigned char)out[n]&0xC0)==0x80))n--;out[n]=0;}strncat(out,"...",cap-strlen(out)-1);}
static void text_center(uint16_t*fb,int y,const char*s,uint16_t c,int scale){char temp[NOISE_TEXT];fit_text(temp,sizeof(temp),s,240/scale);int x=(256-gfx_text_width(temp,scale))/2;if(x<0)x=0;gfx_text(fb,x,y,temp,c,scale);}
static void draw_crown(uint16_t*fb,int x,int y,uint16_t c){gfx_line(fb,x,y+10,x+5,y+2,c);gfx_line(fb,x+5,y+2,x+10,y+9,c);gfx_line(fb,x+10,y+9,x+16,y,c);gfx_line(fb,x+16,y,x+21,y+9,c);gfx_line(fb,x+21,y+9,x+27,y+2,c);gfx_line(fb,x+27,y+2,x+32,y+10,c);gfx_line(fb,x,y+10,x+32,y+10,c);gfx_line(fb,x+2,y+13,x+30,y+13,c);}
static void draw_heart(uint16_t*fb,int x,int y,uint16_t c){gfx_rect(fb,x+2,y,3,3,c);gfx_rect(fb,x+9,y,3,3,c);gfx_line(fb,x+1,y+2,x+6,y+9,c);gfx_line(fb,x+12,y+2,x+7,y+9,c);gfx_line(fb,x+6,y+9,x+7,y+10,c);}
static void draw_play(uint16_t*fb,int x,int y,uint16_t c){for(int i=0;i<12;i++)gfx_line(fb,x+i/2,y+i,x+i/2,y+12-i,c);}
static void draw_pause(uint16_t*fb,int x,int y,uint16_t c){gfx_rect(fb,x,y,3,13,c);gfx_rect(fb,x+7,y,3,13,c);}
void ui_boot_screen(void){uint16_t*t=gfx_top(),*b=gfx_bottom();memcpy(t,boot_top,sizeof(boot_top));memcpy(b,boot_bottom,sizeof(boot_bottom));gfx_present();while(1){scanKeys();if(keysDown()&KEY_A)break;swiWaitForVBlank();}}
static void draw_cover(uint16_t*fb,int x,int y,int size,bool selected,const uint16_t*art){gfx_round(fb,x-3,y-3,size+6,size+6,5,selected?VIOLET:RGB15(8,3,15));gfx_blit(fb,x,y,size,size,art,64,64);if(selected){gfx_rect(fb,x-2,y-2,size+4,1,VIOLET);gfx_rect(fb,x-2,y+size+1,size+4,1,VIOLET);}}
static void draw_top(const NoiseApp*a){uint16_t*fb=gfx_top();gfx_clear(fb,BG);for(int gy=22;gy<110;gy++){int k=(gy-22)/3;uint16_t gc=RGB15(2+k/7,0,k/5);gfx_rect(fb,0,gy,256,1,gc);}for(int i=0;i<18;i++){int sx=(i*47+19)%250,sy=28+(i*23)%78;fb[sy*256+sx]=RGB15(9,3,15);}gfx_rect(fb,0,0,256,2,PURPLE);draw_crown(fb,8,4,VIOLET);gfx_text(fb,48,7,"PROJECT NOISE",WHITE,1);gfx_text(fb,214,7,"DSi",MUTED,1);gfx_line(fb,8,21,248,21,PURPLE);
    int cur=a->playing>=0?a->playing:(a->visible_count?a->visible[a->selected]:-1);static int last_cover=-2,cover_anim=8;if(cur!=last_cover){last_cover=cur;cover_anim=0;}else if(cover_anim<8)cover_anim++;int center_size=68+(cover_anim*6)/8;int center_x=(256-center_size)/2;int center_y=34-(cover_anim*3)/8;int side_shift=(8-cover_anim)/2;draw_cover(fb,21-side_shift,43,42,false,cover_prev);draw_cover(fb,190+side_shift,43,42,false,cover_next);draw_cover(fb,center_x,center_y,center_size,true,cover_logo);
    if(cur>=0&&cur<a->track_count){text_center(fb,111,a->tracks[cur].title,WHITE,1);text_center(fb,122,a->tracks[cur].artist,RGB15(22,17,27),1);}else{text_center(fb,112,"SELECT A TRACK",WHITE,1);text_center(fb,124,"YOUR MUSIC. YOUR WAY.",MUTED,1);}
    gfx_round(fb,16,139,224,5,2,PANEL2);uint32_t dur=cur>=0?a->tracks[cur].duration:0,pos=audio_position_ms()/1000;int pw=dur?((int)(pos*216/dur)):0;if(pw>216)pw=216;if(pw>0)gfx_round(fb,20,140,pw,3,1,VIOLET);
    char tm[24];snprintf(tm,sizeof(tm),"%02lu:%02lu",(unsigned long)(pos/60),(unsigned long)(pos%60));gfx_text(fb,16,148,tm,MUTED,1);if(dur){snprintf(tm,sizeof(tm),"%02lu:%02lu",(unsigned long)(dur/60),(unsigned long)(dur%60));gfx_text(fb,216,148,tm,MUTED,1);}
    int line=lyrics_line_at(audio_position_ms());const LyricLine*ls=lyrics_lines();if(line>=0){if(lyrics_synced()){static int last_line=-2,slide=8;if(line!=last_line){last_line=line;slide=0;}else if(slide<8)slide++;int scale=a->lyrics_font==2?2:1;int y=174+(a->lyrics_animation&&slide<8?(8-slide)/2:0);uint16_t lc=VIOLET;if(a->lyrics_animation){int k=slide>7?7:slide;int ar=accent_color&31,ag=(accent_color>>5)&31,ab=(accent_color>>10)&31;lc=RGB15(5+((ar-5)*k/7),2+((ag-2)*k/7),5+((ab-5)*k/7));}if(line>0)text_center(fb,162,ls[line-1].text,MUTED,1);text_center(fb,y,ls[line].text,lc,scale);if(line+1<lyrics_count())text_center(fb,184,ls[line+1].text,MUTED,1);}else{text_center(fb,158,ls[0].text,WHITE,1);if(lyrics_count()>1)text_center(fb,169,ls[1].text,MUTED,1);if(lyrics_count()>2)text_center(fb,180,ls[2].text,MUTED,1);}}else{text_center(fb,166,lyrics_message(),MUTED,1);}
}
static void draw_tabs(uint16_t*fb,const NoiseApp*a){const char*names[3]={"ALL SONGS","LIKED","QUEUE"};for(int i=0;i<3;i++){int x=8+i*81;uint16_t c=((int)a->tab==i)?VIOLET:PANEL2;gfx_round(fb,x,5,76,17,5,c);int tw=gfx_text_width(names[i],1);gfx_text(fb,x+(76-tw)/2,10,names[i],(int)a->tab==i?WHITE:MUTED,1);}}
static void draw_keyboard(uint16_t*fb){const char*rows[3]={"QWERTYUIOP","ASDFGHJKL","ZXCVBNM"};for(int r=0;r<3;r++){int n=strlen(rows[r]),start=(256-n*20)/2;for(int i=0;i<n;i++){int x=start+i*20;gfx_round(fb,x,108+r*19,17,16,3,PANEL2);char c[2]={rows[r][i],0};gfx_text(fb,x+5,112+r*19,c,WHITE,1);}}gfx_round(fb,14,166,44,17,4,PANEL2);gfx_text(fb,21,171,"SPACE",WHITE,1);gfx_round(fb,65,166,45,17,4,PANEL2);gfx_text(fb,75,171,"DEL",WHITE,1);gfx_round(fb,117,166,124,17,4,PURPLE);gfx_text(fb,164,171,"DONE",WHITE,1);}
static void draw_bottom(const NoiseApp*a){uint16_t*fb=gfx_bottom();gfx_clear(fb,BG);gfx_rect(fb,0,0,256,2,PURPLE);
    if(a->page==PAGE_LYRICS){gfx_text(fb,14,7,"LYRIC MATCHES",WHITE,1);gfx_text(fb,174,7,lyrics_wifi_status(),VIOLET,1);for(int i=0;i<lyrics_match_count();i++){int y=30+i*29;bool sel=i==a->selected;gfx_round(fb,10,y,236,25,5,sel?PANEL2:PANEL);if(sel)gfx_rect(fb,10,y,2,25,VIOLET);char title[NOISE_TEXT],artist[NOISE_TEXT];fit_text(title,sizeof(title),lyrics_match_title(i),208);fit_text(artist,sizeof(artist),lyrics_match_artist(i),208);gfx_text(fb,20,y+4,title,sel?WHITE:MUTED,1);gfx_text(fb,20,y+14,artist,MUTED,1);}gfx_text(fb,16,181,"UP/DOWN SELECT  A OPEN  START BACK",MUTED,1);return;}
    if(a->page==PAGE_SETTINGS){gfx_text(fb,14,7,"SETTINGS",WHITE,1);gfx_text(fb,154,7,lyrics_wifi_status(),VIOLET,1);const char*labels[9]={"SHUFFLE","REPEAT MODE","LYRICS ANIMATION","LYRICS FONT","VOLUME","LIBRARY SORT","OFFLINE LYRICS","CLEAR LYRICS CACHE","THEME"};char val[9][20];snprintf(val[0],20,"%s",a->shuffle?"ON":"OFF");snprintf(val[1],20,"%s",a->repeat_mode==0?"OFF":a->repeat_mode==1?"ALL":"ONE");snprintf(val[2],20,"%s",a->lyrics_animation?"ON":"OFF");snprintf(val[3],20,"%s",a->lyrics_font==0?"SMALL":a->lyrics_font==1?"MEDIUM":"LARGE");snprintf(val[4],20,"%u",a->volume);snprintf(val[5],20,"%s",a->sort_mode==0?"TITLE":a->sort_mode==1?"ARTIST":"ALBUM");snprintf(val[6],20,"%s",a->offline_only?"ON":"OFF");snprintf(val[7],20,"CLEAR");snprintf(val[8],20,"%s",a->theme_mode==0?"VIOLET":a->theme_mode==1?"CYAN":a->theme_mode==2?"CRIMSON":"EMERALD");for(int i=0;i<9;i++){int y=27+i*16;gfx_round(fb,10,y,236,15,4,a->selected==i?PANEL2:PANEL);gfx_text(fb,19,y+4,labels[i],a->selected==i?WHITE:MUTED,1);gfx_text(fb,190,y+4,val[i],VIOLET,1);}gfx_text(fb,16,181,"UP/DOWN SELECT  A CHANGE",MUTED,1);return;}
    draw_tabs(fb,a);gfx_round(fb,8,25,240,18,6,PANEL);gfx_text(fb,16,30,a->search_len?a->search:"SEARCH YOUR LIBRARY",a->search_len?WHITE:MUTED,1);if(a->search_editing){gfx_rect(fb,16+a->search_cursor*8,29,1,10,VIOLET);}else gfx_text(fb,231,30,"/",VIOLET,1);
    int rows=a->search_editing?2:3;int base=a->selected>0?a->selected-1:0;for(int r=0;r<rows;r++){int idx=base+r;if(idx<0||idx>=a->visible_count)continue;int track=a->visible[idx],y=48+r*22;bool selected=idx==a->selected;gfx_round(fb,8,y,240,20,4,selected?PANEL2:PANEL);if(selected){gfx_rect(fb,8,y,2,20,VIOLET);gfx_rect(fb,10,y,238,1,PURPLE);}gfx_round(fb,13,y+3,14,14,3,track==a->playing?PURPLE:RGB15(12,6,19));gfx_text(fb,17,y+6,"N",WHITE,1);char title[NOISE_TEXT],artist[NOISE_TEXT];fit_text(title,sizeof(title),a->tracks[track].title,184);fit_text(artist,sizeof(artist),a->tracks[track].artist,184);gfx_text(fb,34,y+3,title,selected?WHITE:RGB15(23,20,26),1);gfx_text(fb,34,y+12,artist,MUTED,1);if(a->tracks[track].liked)draw_heart(fb,228,y+5,VIOLET);if(track==a->playing){gfx_rect(fb,213,y+5,2,10,VIOLET);gfx_rect(fb,217,y+2,2,13,VIOLET);gfx_rect(fb,221,y+7,2,8,VIOLET);}}
    if(a->search_editing){draw_keyboard(fb);}else{gfx_text(fb,16,116,"NOW PLAYING",VIOLET,1);if(a->playing>=0){char np[NOISE_TEXT];fit_text(np,sizeof(np),a->tracks[a->playing].title,136);gfx_text(fb,104,116,np,WHITE,1);}else gfx_text(fb,104,116,"NOTHING PLAYING",MUTED,1);gfx_circle(fb,128,160,29,PANEL2);gfx_circle(fb,128,160,27,VIOLET);gfx_circle(fb,128,160,25,RGB15(10,4,19));gfx_fill_circle(fb,128,160,12,PANEL2);gfx_circle(fb,128,160,12,VIOLET);gfx_text(fb,106,134,"SEARCH",WHITE,1);gfx_text(fb,87,157,"PREV",WHITE,1);gfx_text(fb,143,157,"NEXT",WHITE,1);gfx_text(fb,111,178,"LIKE",WHITE,1);if(a->paused||!a->playing_now)draw_play(fb,123,154,VIOLET);else draw_pause(fb,123,153,VIOLET);}
    if(a->status_frames){gfx_round(fb,64,126,128,15,5,PURPLE);text_center(fb,130,a->status,WHITE,1);}}
void ui_draw(const NoiseApp*a){static const uint16_t themes[4]={RGB15(31,4,31),RGB15(4,24,31),RGB15(31,4,8),RGB15(5,29,12)};accent_color=themes[a->theme_mode%4];draw_top(a);draw_bottom(a);gfx_present();}
void ui_touch(NoiseApp*a,int x,int y){
    if(a->page==PAGE_LYRICS){if(y>=30&&y<175){int idx=(y-30)/29;if(idx>=0&&idx<lyrics_match_count()){a->selected=idx;lyrics_select_match(idx);a->page=PAGE_LIBRARY;noise_status("FETCHING LYRIC MATCH");}}return;}
    if(a->page==PAGE_SETTINGS){if(y>=27&&y<172){int row=(y-27)/16;if(row>=0&&row<9){a->selected=row;if(row==0)a->shuffle=!a->shuffle;else if(row==1)a->repeat_mode=(a->repeat_mode+1)%3;else if(row==2)a->lyrics_animation=!a->lyrics_animation;else if(row==3)a->lyrics_font=(a->lyrics_font+1)%3;else if(row==4){a->volume=(uint8_t)(a->volume+32);audio_set_volume(a->volume);}else if(row==5){a->sort_mode=(a->sort_mode+1)%3;library_rebuild_visible(a);}else if(row==6)a->offline_only=!a->offline_only;else if(row==7)lyrics_clear_cache();else if(row==8)a->theme_mode=(a->theme_mode+1)%4;settings_save(a);}}return;}
    if(y>=5&&y<23){if(x<88)a->tab=TAB_ALL;else if(x<170)a->tab=TAB_LIKED;else a->tab=TAB_QUEUE;a->page=PAGE_LIBRARY;a->selected=0;library_rebuild_visible(a);return;}
    if(y>=25&&y<44){a->page=PAGE_SEARCH;a->search_editing=true;a->search_cursor=a->search_len;library_rebuild_visible(a);return;}
    if(a->search_editing&&y>=108){const char*rows[3]={"QWERTYUIOP","ASDFGHJKL","ZXCVBNM"};if(y<165){int row=(y-108)/19;int n=strlen(rows[row]);int start=(256-n*20)/2;int col=(x-start)/20;if(col>=0&&col<n&&x>=start+col*20&&x<start+col*20+17&&a->search_len<27){memmove(a->search+a->search_cursor+1,a->search+a->search_cursor,a->search_len-a->search_cursor+1);a->search[a->search_cursor++]=rows[row][col];a->search_len++;library_rebuild_visible(a);}}else if(x<60){if(a->search_len<27){memmove(a->search+a->search_cursor+1,a->search+a->search_cursor,a->search_len-a->search_cursor+1);a->search[a->search_cursor++]=' ';a->search_len++;library_rebuild_visible(a);}}else if(x<112){if(a->search_cursor>0){memmove(a->search+a->search_cursor-1,a->search+a->search_cursor,a->search_len-a->search_cursor+1);a->search_cursor--;a->search_len--;library_rebuild_visible(a);}}else{a->search_editing=false;}return;}
    if(y>=48&&y<114){int row=(y-48)/22;int base=a->selected>0?a->selected-1:0;int idx=base+row;if(idx>=0&&idx<a->visible_count){a->selected=idx;}}
    if(y>=130&&y<190){int dx=x-128,dy=y-160;if(dx*dx+dy*dy<=34*34){if(dy<-12){a->page=PAGE_SEARCH;a->search_editing=true;a->search_cursor=a->search_len;library_rebuild_visible(a);}else if(dx<-12)input_previous_track(a);else if(dx>12)input_next_track(a);else if(dy>12)input_toggle_like(a);else input_toggle_play(a);}}
}
